#!/usr/bin/env python3
# luxarch:luxpm-close-tracks-deferrals hook v9 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a close summary whose labelled deferral names no issue that tracks it.

PreToolUse(luxpm_update_issue, luxpm_create_issue): every `close_summary` the call writes (the
single form, each `updates[]` entry, a create filed as done) is read for LABELLED SLOTS only. A
slot is a line, a bullet or a sentence that opens with one of these labels and a colon, bold or
not, in any case: `Not built:`, `Deferred:`, `Follow-up:` (or `Follow-ups:`), `TODO:`, `Left:`,
`Remaining:`, `Out of scope:`. A label may carry words from a closed set before its colon: `here`,
`yet`, `filed`, `open`, `on purpose`, `work`, `items`, `over`, `gap`, `check`, `as noted`,
`for the owner`, `red`, `lit`, `alone`, `at close`, `deliberately`, `and tracked`, `, not in this
issue`, or a parenthesis (`**Not built here:**`, `Not built (stated limits):`, `Left red on
purpose:`, `Remaining gap:`). A slot is also a sentence holding one of a few fixed phrases that say work is left:
"not yet built", "not built yet", "will be done later", "left for later", "deferred to a later
…" / "deferred to a future …", "in a later release" / "in a future release", "a future
tightening".

A slot passes when it names another issue's key (`<ticket>`) or says `dropped` with its reason
(`dropped: <why>`, `dropped, because …`), or when its next sentence is a pointer that does ("Not
built: X. That's AB-12."). A lead-in with nothing after its colon ("**Not built:**") hands that
duty to each bullet under it. A slot whose whole content is "none", "nothing" or "n/a" defers
nothing, and so does a `Follow-up (<sha>):` (the commit that shipped it), a follow-up removal
in fixed words naming its commit ("Follow-ups: `x` was removed in `a1b2c3d`."), or a removal in
fixed words under any other label ("Left for the owner: `x` is gone, and with it `y`.").

Every other sentence passes, whatever words it uses: the hook does not read free prose. A deferral
written as prose ("The Windows port is deferred.") reaches `/luxpm-audit`, whose `--scan` reads
the prose of every closed summary and reports each sentence that looks like a deferral, for the
auditing agent or a person to judge one by one. Write a deferral in a labelled slot, so the hook
holds it at the close.

`--scan FILE` reads a JSON object of `{"<KEY>": "<close summary>"}` and prints each sentence its
prose reading takes for an untracked deferral as `<KEY>: <sentence>`, exiting 1 when there is one
and 2 when the file is not such an object. It is a report, never a denial: its readings are below
the hook, in their own section.

A denial that is wrong is reported with `/escalate`, and the sentence stays as written.

**Why a hook.** A close summary lives on a closed issue, and a closed issue is in no open list, no
focus digest and no backlog sweep: work written only there is tracked by nothing. The rule's home
is `/wrap-up` step 6 ("A close summary is not a tracker"); this makes it hold for the slots that
say so in their label. It reads only the text the call carries, so it cannot tell whether a cited
key is open: citing one is the agent's statement that it is. Fails OPEN on input it cannot read: a
hook that blocks on its own uncertainty gets switched off.
"""

from __future__ import annotations

import json
import re
import sys

_KEY = re.compile(r"\b[A-Z][A-Z0-9]{1,15}-\d+\b")
_BULLET = re.compile(r"^\s*(?:[-*+]|\d+[.)])\s+")
# A sentence ends at . ! or ? and the whitespace after it, after any closing bold or italic marks.
_SENTENCE = re.compile(r"(?<=[.!?])((?:\*\*|\*|__|_)?)\s+")
_HEX = r"(?=[0-9a-f]*[a-f])(?=[0-9a-f]*[0-9])[0-9a-f]{7,40}"
_POINTER = re.compile(
    r"^(?:[Tt]hat|[Tt]his|[Ii]t|[Tt]racked|[Ff]iled)\b"
    r"|^[A-Z][A-Z0-9]{1,15}-\d+\s+(?:tracks|covers|has)\s+(?:it|this|that)\s*[.!]?\s*$"
)
# A removal in fixed words, with names in code spans only: "`ImageRole` is gone, and with it `x`".
_CS = r"`[^`\s]+`"
_CS_LIST = rf"{_CS}(?:\s*(?:/|,|&|and)\s*{_CS})*"
_REMOVED = r"(?:is|are|was|were|has\s+been|have\s+been)\s+(?:gone|removed|deleted)"
_IN_COMMIT = rf"\s+in\s+(?:commit\s+)?`?{_HEX}`?"
_WITH_IT = rf"(?:\s*,?\s*(?:and\s+)?with\s+(?:it|them)\s+{_CS_LIST})?\s*[.!]?"

# ── the hook: labelled slots ──────────────────────────────────────────────────────────────────
_LABEL = re.compile(
    r"(?P<label>not\s+built|deferred|follow[- ]?ups?|todo|left|remaining|out\s+of\s+scope)"
    r"(?P<qual>(?:\s+(?:here|yet|filed|open|on\s+purpose|work|items|over|gap|check"
    r"|as\s+noted|for\s+the\s+owner|red|lit|alone|at\s+close|deliberately|and\s+tracked)"
    r"|\s*,\s*(?:filed|not\s+in\s+this\s+issue)|\s*\([^()]*\))*)"
    r"\s*:\s*(?P<rest>.*)",
    re.IGNORECASE | re.DOTALL,
)
_PHRASES = re.compile(
    r"\bnot\s+yet\s+built\b|\bnot\s+built\s+yet\b|\bwill\s+be\s+done\s+later\b"
    r"|\bleft\s+for\s+later\b|\bdeferred\s+to\s+an?\s+(?:later|future)\b"
    r"|\bin\s+an?\s+(?:later|future)\s+release\b|\ba\s+future\s+tightening\b",
    re.IGNORECASE,
)
_NONE = re.compile(
    r"(?:none|nothing|n/a)(?:\s+(?:needed|required))?\s*[.!]?", re.IGNORECASE
)
# Any other label's content may be the same removal with no commit: "Left for the owner: `x` is gone".
_LEFT_GONE = re.compile(
    rf"{_CS_LIST}\s+{_REMOVED}(?:{_IN_COMMIT})?{_WITH_IT}", re.IGNORECASE
)
_SLOT_GONE = re.compile(
    rf"{_CS_LIST}\s+{_REMOVED}{_IN_COMMIT}{_WITH_IT}", re.IGNORECASE
)
# `dropped` with its reason; "not dropped" is no drop.
_DROPPED = re.compile(
    r"(?<!\bnot\s)\bdropped\b\s*(?::|,|—|–|\s+(?:because|as|since|by))\s*\S",
    re.IGNORECASE,
)


def _plain(text: str) -> str:
    """The text with its bullet marker and bold or italic marks taken off."""
    return _BULLET.sub("", text.replace("*", "")).strip().strip("_").strip()


def _slot(text: str) -> str | None:
    """The label or phrase that makes this sentence a slot, or None. A label's content that says
    nothing remains, a Follow-up naming its shipping commit or removal, or a removal in fixed
    words under any other label, is no slot."""
    m = _LABEL.match(_plain(text))
    if m:
        rest = m.group("rest").strip()
        follow = m.group("label").lower().startswith("follow")
        if _NONE.fullmatch(rest):
            return None
        if follow and (re.search(_HEX, m.group("qual")) or _SLOT_GONE.fullmatch(rest)):
            return None
        if not follow and _LEFT_GONE.fullmatch(rest):
            return None
        return m.group("label") + m.group("qual") + ":"
    p = _PHRASES.search(text)
    return f'"{p.group(0)}"' if p else None


def _tracked(text: str, own: str) -> bool:
    return bool(_DROPPED.search(text)) or any(k != own for k in _KEY.findall(text))


def _own_key(entry: dict[str, object], project: object) -> str:
    seq = str(entry.get("sequence_id") or "").strip().upper()
    if "-" in seq or not seq:
        return seq
    proj = str(entry.get("project") or project or "").strip().upper()
    return f"{proj}-{seq}" if proj else seq


def _sentences(text: str) -> list[str]:
    """Split at each sentence end, keeping a closing bold or italic mark on its own sentence."""
    out: list[str] = []
    start = 0
    for m in _SENTENCE.finditer(text):
        out.append(text[start : m.end(1)])
        start = m.end()
    out.append(text[start:])
    return out


def untracked(summary: str, own: str) -> list[tuple[str, str]]:
    """Each (slot, sentence or bullet) whose labelled deferral names no other issue and no
    `dropped` with a reason."""
    out: list[tuple[str, str]] = []
    lines = summary.splitlines()
    k = 0
    while k < len(lines):
        plain = lines[k].strip()
        k += 1
        if not plain:
            continue
        lead = _LABEL.match(_plain(plain))
        if lead and not lead.group("rest").strip() and not _tracked(plain, own):
            # a lead-in: each bullet under it (until a blank line or a non-bullet) carries the duty
            slot = lead.group("label") + lead.group("qual") + ":"
            under = False
            while k < len(lines) and (
                _BULLET.match(lines[k]) or (under and lines[k].startswith((" ", "\t")))
            ):
                if _BULLET.match(lines[k]):
                    under = True
                    if not _tracked(lines[k], own):
                        out.append((slot, lines[k].strip()))
                k += 1
            if not under:
                out.append((slot, plain))
            continue
        sentences = _sentences(plain)
        for i, sentence in enumerate(sentences):
            slot = _slot(sentence)
            if slot is None or _tracked(sentence, own):
                continue
            nxt = sentences[i + 1] if i + 1 < len(sentences) else ""
            if not (_POINTER.match(nxt) and _tracked(nxt, own)):
                out.append((slot, sentence.strip()))
    return out


def _closes(tool_input: dict[str, object]) -> list[tuple[str, str]]:
    entries: list[dict[str, object]] = [tool_input]
    updates = tool_input.get("updates")
    if isinstance(updates, list):
        entries += [u for u in updates if isinstance(u, dict)]
    project = tool_input.get("project")
    out: list[tuple[str, str]] = []
    for e in entries:
        summary = e.get("close_summary")
        if isinstance(summary, str) and summary.strip():
            out.append((_own_key(e, project), summary))
    return out


def main() -> int:
    if len(sys.argv) == 3 and sys.argv[1] == "--scan":
        return scan(sys.argv[2])
    try:
        ev = json.load(sys.stdin) or {}
        ti = ev.get("tool_input")
        closes = _closes(ti if isinstance(ti, dict) else {})
    except Exception:
        return 0  # hooks fail OPEN
    found = [
        (own, slot, s) for own, summary in closes for slot, s in untracked(summary, own)
    ]
    if not found:
        return 0
    lines = "\n".join(
        f"  - {own or 'this issue'}, slot `{slot}`: {s[:200]}" for own, slot, s in found
    )
    print(
        "DENIED: this close summary has a labelled deferral that no open issue tracks. A closed "
        "issue is in no open list, focus or backlog sweep, so work written only into its summary "
        f"is lost:\n{lines}\n"
        "For each slot, one of two remedies: search LuxPM, file the work as its own open issue (or "
        "comment on the open one that covers it) and name that key in the slot, e.g. "
        "`Not built: X (<ticket>)`; or, for work you decided against, write `dropped: <why>` in "
        "it. Then close again. Rewording a true slot to get past this is not a fix: when the slot "
        "defers nothing, leave it as it is and report the denial with /escalate. "
        'See /wrap-up step 6, "A close summary is not a tracker".',
        file=sys.stderr,
    )
    return 2


# ── --scan: the prose backstop, a report for /luxpm-audit, never a denial ─────────────────────
# It reads every sentence of free prose for a deferral word and leaves out the shapes that defer
# nothing: the fixed forms that say nothing remains ("Nothing deferred."), names in code spans, a
# rule that does not run on a kind of repo, "untested" that reports coverage added, a reported
# fact or named thing in its own grammar (a follow-up request, a TODO tag, a gate's tally, …) in a
# sentence with no work ahead, a mechanism's state defined for a class of things, and a stated
# limit recorded in its docstring, changelog entry or close summary. Each hit is judged by a reader.

_DEFERS = re.compile(
    r"\b(?:not\s+(?:yet\s+)?(?:built|done|fixed|implemented|handled|covered|shipped|filed|tracked"
    r"|verified|confirmed|checked|tested|run|taken|asked)"
    r"|did\s+not\s+(?:build|do|fix|ship|verify|check)|unconfirmed|inconclusive|unverified"
    r"|untested"
    r"|open\s+(?:owner\s+)?questions?|left\s+in\s+place"
    r"|deferred|defer(?:s|ring)?\b|follow[- ]?ups?\b"
    r"|a\s+future\s+(?:tightening|rule|check|release|cut|pass|version|change)"
    r"|out\s+of\s+scope|(?:stated|known)\s+(?:limits?|limitations?)\b"
    r"|left\s+(?:for|as\s+is|open)|for\s+later|(?:a|in\s+a)\s+later\s+(?:cut|release|pass|version)"
    r"|next\s+(?:release|cut|pass)|todo\b|unreproduced|not\s+reproduced"
    r"|still\s+(?:open|to\s+do|missing)|remains?\s+(?:open|to\s+(?:do|be))|(?:filed|tracked|handled)\s+separately)",
    re.IGNORECASE,
)
_ANY_DROPPED = re.compile(r"\bdropped\b", re.IGNORECASE)
# A code span with no space is a name, not prose (`[rules.deferred]`), and so is luxarch's own
# summary count `0 xfail (deferred)` (a count above 0 is deferred tests, and reads as such).
_CODE = re.compile(r"`[^`\s]+`|\b0\s+xfail\s+\(deferred\)", re.IGNORECASE)
# A follow-up that names the commit that shipped it: `Follow-up (<sha>)`.
_SHIPPED = re.compile(rf"follow[- ]?ups?\s*\([^)]*\b{_HEX}\b[^)]*\)", re.IGNORECASE)
_FOLLOW_UP = r"follow[- ]?ups?"
_REMAINDER = (
    rf"(?:{_FOLLOW_UP}|deferrals?|deferred\s+work|(?:stated|known)\s+limit(?:ation)?s?"
    r"|open\s+questions?)"
)
_NEEDED = r"(?:needed|required|remains?|remaining|left)"
_SHIPPED_ALL = r"(?:full\s+scope|everything|all\s+of\s+it|all)\s+shipped"
_JOIN = r"\s*[,;—–-]\s*"
# The commit or version that shipped it, as a fixed-word lead: "Shipped in `c83acc8`, both halves".
_REF = rf"`?(?:{_HEX}|v?\d+\.\d+\.\d+)`?"
_SHIPPED_IN = (
    rf"(?:shipped|landed|fixed|done|merged)(?:\s+in\s+(?:commit\s+)?{_REF}(?:\s*(?:,|\+|and)\s*{_REF})*)?"
    r"(?:\s*,\s*(?:both\s+halves|in\s+full|all\s+of\s+it|every\s+part|end\s+to\s+end))?"
)
# The sentences that say nothing remains, made of FIXED words only, and only as the WHOLE sentence.
# No slot takes free text, so no wording of remaining work can ride inside one: every form a past
# attack used for that (a free subject, a reason after a colon, trailing items) is not read here.
_NOTHING_LEFT = re.compile(
    rf"(?:(?:{_SHIPPED_ALL}|{_SHIPPED_IN}){_JOIN})?"
    r"(?:"
    r"(?:nothing|none)\s+(?:(?:is|was|has\s+been)\s+)?(?:being\s+)?(?:left\s+)?deferred"
    r"|nothing\s+was\s+deferred\s+and\s+nothing\s+is\s+left\s+open"
    rf"|no\s+(?:(?:further|new|additional|remaining|outstanding)\s+)?{_REMAINDER}(?:\s+work)?"
    rf"(?:\s+(?:or|and)\s+{_REMAINDER})?(?:\s+(?:(?:is|are|was|were)\s+)?{_NEEDED})?"
    rf"|there\s+(?:is|are)\s+no\s+{_REMAINDER}(?:\s+{_NEEDED})?"
    rf"|(?:{_REMAINDER}|deferred|not\s+built)\s*(?::|—|–|-)\s*(?:none|nothing|n/a)"
    r"(?:\s+(?:needed|required))?"
    rf"|{_REMAINDER}\s+(?:(?:is|are)\s+)?not\s+(?:needed|required)"
    r"|(?:(?:i|we)\s+)?(?:did\s+not|didn't)\s+defer\s+anything"
    rf"|(?:(?:i|we)\s+)?(?:will\s+not|won't)\s+need\s+an?\s+{_FOLLOW_UP}"
    r"|(?:the|all|every)\s+open\s+questions?(?:\s+on\s+this\s+(?:ticket|issue))?\s+"
    r"(?:(?:is|are|was|were)\s+)?(?:(?:therefore|now|all|already)\s+)?(?:answered|resolved|settled)"
    r"|(?:the|all|every)\s+open\s+questions?\s*,\s*(?:answered|resolved|settled)"
    r"(?:\s+(?:in\s+the\s+code|below|here))?"
    r")"
    rf"(?:{_JOIN}{_SHIPPED_ALL})?\s*[.!]?",
    re.IGNORECASE,
)
_GONE = re.compile(
    r"(?:(?:left\s+for\s+(?:the\s+)?(?:owner|maintainer)\s*:\s*)?"
    rf"{_CS_LIST}\s+{_REMOVED}(?:{_IN_COMMIT})?"
    rf"|(?:follow[- ]?ups?|open\s+questions?)\s*:\s*{_CS_LIST}\s+{_REMOVED}{_IN_COMMIT})"
    rf"{_WITH_IT}",
    re.IGNORECASE,
)


def _says_nothing_left(text: str) -> bool:
    """The whole sentence (a bullet's text, bold and curly apostrophes aside) is one of the fixed
    forms that say nothing remains."""
    s = text.replace("’", "'").replace("*", "").strip()
    return bool(_NOTHING_LEFT.fullmatch(_BULLET.sub("", s).strip()))


def _read(text: str) -> str:
    """The sentence as prose to check: names and the shipping commit taken out."""
    return _SHIPPED.sub("", text)


def _name(m: re.Match[str]) -> str:
    """A code span is a name; a commit in one stays readable as the commit."""
    inner = m.group(0).strip("`")
    return inner if re.fullmatch(_HEX, inner) else "``"


# "Nothing is left untested." as the whole sentence, or as its last clause after a `;`: fixed
# words, no qualifier before them ("Almost nothing …", "Except X, nothing …") and nothing after.
_NOTHING_UNTESTED = re.compile(
    r"(?:^|;\s*)nothing\s+(?:is\s+|was\s+)?(?:left\s+)?untested\s*[.!]?\s*$",
    re.IGNORECASE,
)
# The untested part as the subject of a past-tense clause, with the coverage added said of IT: the
# sentence ends "…, and it is now covered." (or tested), or it opens with the file's coverage
# rising ("`ws.py` 45% → 77% — the untested half was …").
_BEFORE_STATE = re.compile(
    r"\bthe\s+untested(?:\s+[\w.-]+){1,3}?\s+(?:was|were)\b", re.IGNORECASE
)
_NOW_COVERED = re.compile(
    r",?\s+and\s+(?:it|they)\s+(?:is|are)\s+now\s+(?:covered|tested)\s*[.!]?\s*$",
    re.IGNORECASE,
)
_COVERAGE_ROSE = re.compile(
    r"^\W*[\w./`-]+\W*\s+(\d+(?:\.\d+)?)\s*%\s*(?:→|->)\s*(\d+(?:\.\d+)?)\s*%\W*\s*(?:—|–|-|:)\s*the\s+untested\b",
    re.IGNORECASE,
)
_UNTESTED = re.compile(r"\buntested\b", re.IGNORECASE)
# A rule or check, the sentence's subject, that does not run on a kind of repo or place: where it
# applies, not work left undone. Only that subject, with a short complement ending the clause.
_DOES_NOT_APPLY = re.compile(
    r"^(?:the|this|these|those|both|each|its)(?:\s+[\w.-]+){0,3}?\s+(?:rules?|checks?|guards?|hooks?)\b"
    r"(?:(?!\b(?:i|we|our|us|you)\b)[^;.])*?\b(?:do|does)\s+not\s+run"
    r"(?=(?:\s+(?:on|in|for|against|outside|over)(?:\s+(?!(?:and|but|until|so|because|yet|now|anymore)\b)[\w./`'-]+){1,5}|\s+(?:here|there))\s*(?:[.;!]|$))",
    re.IGNORECASE,
)


def _scope_reported(prose: str) -> str:
    """The prose with a "do/does not run" that says where a rule or check applies taken out."""
    m = _DOES_NOT_APPLY.match(prose.strip())
    return prose.replace(m.group(0), " ", 1) if m else prose


# Future, modal or pending wording: work still ahead. A sentence carrying any of it is read as it
# always was, whatever else it reports ("v7 or later" is a version range, not a time).
_AHEAD = re.compile(
    r"\b(?:will|shall|would|should|must|going\s+to|needs?\s+to|has\s+to|have\s+to|plan(?:s|ned)?"
    r"|pending|yet|soon|eventually|next|(?<!or\s)later)\b|\bwon[’']t\b",
    re.IGNORECASE,
)
# What a sentence reports or names, each read only in its own fixed grammar:
_FACTS = [
    # "follow-up" premodifying a request the software makes ("arrive on follow-up HTMX requests")
    re.compile(
        r"\bfollow-ups?\s+(?:[A-Z]{2,}\s+)?(?:requests?|calls?|quer(?:y|ies)|fetch(?:es)?"
        r"|responses?|polls?|navigations?|round-trips?)\b"
    ),
    # TODO as the name of a code tag in a list of tags ("(TODO/FIXME/BUG/HACK)")
    re.compile(r"\b(?:[A-Z]{2,}/)*TODO(?:/[A-Z]{2,})+\b|\b(?:[A-Z]{2,}/)+TODO\b"),
    # TODO as a board state left behind ("moved from TODO to done", "TODO -> done")
    re.compile(r"\bfrom\s+TODO\s+to\s+[\w-]+|\bTODO\s*(?:→|->)\s*[\w-]+"),
    # a TODO that is gone, the subject of a removal in the present perfect or past
    re.compile(
        r"\bTODO\s+(?:(?:comment|marker|stub)s?\s+)?(?:is|are|was|were|has\s+been|have\s+been)\s+"
        r"(?:gone|removed|deleted|resolved)\b"
    ),
    # a quotation used as a name: the object of "means"/"called", or a quoted label
    re.compile(
        r"\b(?:means|meant|meaning|named|called|label(?:l)?ed|titled)\s+(?:\"[^\"]*\"|“[^”]*”)"
        r"|(?:\"[^\"]*\"|“[^”]*”)\s+(?:label|tag|line|message|string|text|heading|title|button"
        r"|column|field|option)s?\b",
        re.IGNORECASE,
    ),
    # the ticket itself, left open after its work landed (its state, not work)
    re.compile(
        r"\b(?:this|this\s+(?:ticket|issue)|the\s+(?:ticket|issue))\s+(?:was|had\s+been)\s+left\s+open"
        r"(?:\s+on\s+my\s+side)?\s+after\s+(?:[\w`.-]+\s+){1,4}?(?:landed|shipped|merged)(?=\s*(?:[.;,]|$))",
        re.IGNORECASE,
    ),
    # a gate's tally, `<n> passed / <n> failed / <n> <status>`, with "deferred" one of its counts
    re.compile(
        r"\b\d+\s+passed\s*/\s*\d+\s+failed(?:\s*/\s*\d+\s+[a-z]+)+(?=\s*(?:[.;,]|$))",
        re.IGNORECASE,
    ),
    # a self-correction: the writer's own inference, named as one they did not check
    re.compile(
        r"^\W*correction\b[^:]*:\s*(?:i|we)\s+(?:inferred|assumed|guessed|thought|concluded|believed"
        r"|supposed|reasoned)\b[^;]*?,?\s+but\s+did\s+not\s+(?:verify|check|confirm)\s+(?:it|that|this)"
        r"\s*[.!]?\s*$",
        re.IGNORECASE,
    ),
    # follow-ups as what a mechanism looks for ("commits are checked for untracked follow-ups")
    re.compile(
        r"(?<!\bnot\s)(?<!\bnever\s)(?<!n't\s)"
        r"\b(?:checked|scanned|searched|audited|checks|scans|searches|looks)\s+for\s+"
        r"(?:untracked\s+|unfiled\s+)?follow-ups\b",
        re.IGNORECASE,
    ),
]


# A mechanism's named state, defined for a class of things: an indefinite or universal subject
# with a restrictive clause, a copula and the state as the sentence's last word ("A round that
# executed nothing is INCONCLUSIVE."). A definite subject or none ("The round …", "Round 2 is …",
# "A race on reconnect is …") reports the state of one thing, and is read as before.
_STATE = r"(?:inconclusive|unconfirmed|unreproduced|unverified|failed|pending|deferred)"
_DEFINED_STATE = re.compile(
    r"(?P<subject>(?:a|an|any|every|each)(?:\s+[\w.-]+){1,5}?"
    r"\s+(?:that|which|whose|in\s+which|for\s+which)\b[^,;:]*?)"
    r"\s+(?:is|are|reads|read|counts|is\s+(?:marked|reported|recorded|read|counted))"
    rf"(?:\s+as)?\s+{_STATE}\s*[.!]?",
    re.IGNORECASE,
)
# A stated limit recorded in the home the adversarial skill names for one: the docstring, the
# changelog entry or the close summary. Recorded there, it is tracked, not deferred.
_HOME = (
    r"(?:(?:the|its|their|this)\s+)?(?:"
    r"(?:(?:rule|rule's|hook|hook's|asset|asset's|module|function|class|skill)\s+)?docstrings?"
    r"|(?:``\s+|v?\d+\.\d+\.\d+\s+)?(?:changelog|change\s+log)(?:\s+entry)?"
    r"|close\s+summary)"
)
_LIMITS_RECORDED = re.compile(
    r"(?:(?:the|its|their|all)\s+)?(?:stated|known)\s+limit(?:s|ations?)?"
    r"(?P<subject>(?:\s+(?:of|on|for)(?:\s+[\w.`'-]+){1,4}?)?)"
    r"\s+(?:is|are|was|were|has\s+been|have\s+been)\s+(?:recorded|stated|written|documented|listed)"
    rf"\s+in\s+{_HOME}(?:\s*(?:,\s*(?:and\s+)?|and\s+){_HOME})*\s*[.!]?",
    re.IGNORECASE,
)
_FIRST_PERSON = re.compile(r"\b(?:i|we|our|us|my)\b", re.IGNORECASE)


def _defined_or_recorded(prose: str) -> bool:
    """The whole sentence defines a mechanism's state or records a stated limit in its home, and
    its free subject carries no deferral, no work ahead and no first-person report."""
    s = _BULLET.sub("", prose.replace("*", "")).strip()
    m = _DEFINED_STATE.fullmatch(s) or _LIMITS_RECORDED.fullmatch(s)
    if not m:
        return False
    subject = m.group("subject")
    return not (
        _DEFERS.search(subject)
        or _AHEAD.search(subject)
        or _FIRST_PERSON.search(subject)
    )


def _facts_reported(prose: str) -> str:
    """The prose with each reported fact or named thing taken out, in a sentence with no work ahead."""
    if _AHEAD.search(prose):
        return prose
    for fact in _FACTS:
        prose = fact.sub(" ", prose)
    return prose


def _untested_reported(prose: str) -> str:
    """The prose with an "untested" that reports coverage, not a gap, taken out."""
    text = prose.strip()
    if _NOTHING_UNTESTED.search(text) and len(_UNTESTED.findall(text)) == 1:
        return _UNTESTED.sub(" ", prose)
    if len(_UNTESTED.findall(text)) != 1 or not _BEFORE_STATE.search(text):
        return prose
    rose = _COVERAGE_ROSE.search(text)
    if _NOW_COVERED.search(text) or (
        rose and float(rose.group(1)) < float(rose.group(2))
    ):
        return _UNTESTED.sub(" ", prose)
    return prose


def _defers(text: str) -> bool:
    if _says_nothing_left(text):
        return False
    lead = _BULLET.sub("", text.replace("’", "'").replace("*", "")).strip()
    if _GONE.fullmatch(lead):
        return False
    named = _read(_CODE.sub(_name, text))
    if _defined_or_recorded(named):
        return False
    prose = _facts_reported(_scope_reported(_untested_reported(named)))
    return bool(_DEFERS.search(prose))


def _prose_tracked(text: str, own: str) -> bool:
    return bool(_ANY_DROPPED.search(text)) or any(k != own for k in _KEY.findall(text))


def prose_untracked(summary: str, own: str) -> list[str]:
    """Each sentence (or bullet under a deferring lead-in) that defers work and names no other
    issue and no `dropped`."""
    out: list[str] = []
    lines = summary.splitlines()
    k = 0
    while k < len(lines):
        line = lines[k]
        k += 1
        plain = line.strip().strip("*_ ").rstrip("*_ ")
        if not plain:
            continue
        if _defers(plain) and plain.endswith(":") and not _prose_tracked(plain, own):
            # a lead-in: each bullet under it (until a blank line or a non-bullet) carries the duty
            under = False
            while k < len(lines) and (
                _BULLET.match(lines[k]) or (under and lines[k].startswith((" ", "\t")))
            ):
                if _BULLET.match(lines[k]):
                    under = True
                    if not _prose_tracked(lines[k], own):
                        out.append(lines[k].strip())
                k += 1
            if not under:
                out.append(plain)
            continue
        sentences = _sentences(plain)
        for i, sentence in enumerate(sentences):
            nxt = sentences[i + 1] if i + 1 < len(sentences) else ""
            handed = bool(_POINTER.match(nxt)) and _prose_tracked(nxt, own)
            if _defers(sentence) and not _prose_tracked(sentence, own) and not handed:
                out.append(sentence.strip())
    return out


# One name for both, so the clause reads the same under every Python target (PEP 758).
_UNREADABLE = (OSError, ValueError, RecursionError)


def scan(path: str) -> int:
    try:
        with open(path, encoding="utf-8") as f:
            summaries = json.load(f)
    except _UNREADABLE:
        summaries = None
    if not isinstance(summaries, dict) or not all(
        v is None or isinstance(v, str) for v in summaries.values()
    ):
        print(
            '--scan reads a JSON object: {"<KEY>": "<close summary>" or null}',
            file=sys.stderr,
        )
        return 2
    found = [
        f"{key}: {s}"
        for key, summary in summaries.items()
        if isinstance(summary, str)
        for s in prose_untracked(summary, str(key).upper())
    ]
    print("\n".join(found) if found else "no untracked deferrals")
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
